+/**
+ * @test
+ * @bug 8397394
+ * @summary Verify dangling doc comments are handled properly
+ * @library /tools/lib /tools/javac/lib
+ * @modules jdk.compiler/com.sun.tools.javac.api
+ *          jdk.compiler/com.sun.tools.javac.main
+ *          jdk.compiler/com.sun.tools.javac.util
+ * @compile DanglingDocComments.java
+ * @build toolbox.ToolBox
+ * @run junit DanglingDocComments
+ */
+
+import java.io.IOException;
+import java.nio.file.Files;
+import java.nio.file.Path;
+import java.nio.file.Paths;
+import java.util.ArrayList;
+import java.util.List;
+import java.util.Set;
+import javax.annotation.processing.RoundEnvironment;
+import javax.lang.model.element.TypeElement;
+import org.junit.jupiter.api.Test;
+import org.junit.jupiter.api.TestInfo;
+import toolbox.JavacTask;
+import toolbox.Task;
+import toolbox.ToolBox;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+public class DanglingDocComments {
+    private final Path base;
+    private final ToolBox tb = new ToolBox();
+
+    public DanglingDocComments(TestInfo info) {
+        base = Paths.get(".")
+                    .resolve(info.getTestMethod()
+                                 .orElseThrow()
+                                 .getName());
+    }
+
+    @Test
+    public void testDanglingDocCommentsWithAP() throws IOException {
+        Path classes = base.resolve("classes");
+
+        Files.createDirectories(classes);
+
+        List<String> expected = List.of(
+            "Test.java:2:5: compiler.warn.dangling.doc.comment",
+            "1 warning"
+        );
+        for (List<String> options : List.of(List.<String>of(),
+                                            List.of("-processor", ProcessorImpl.class.getName(),
+                                                    "-processorpath", System.getProperty("test.classes")))) {
+            List<String> allOptions = new ArrayList<>();
+
+            allOptions.add("-XDrawDiagnostics");
+            allOptions.add("-Xlint:all");
+            allOptions.addAll(options);
+            List<String> out =
+                new JavacTask(tb)
+                        .sources("""
+                                 public class Test {
+                                     /**comment1*/
+                                     /**comment2*/
+                                     public void test() {}
+                                 }
+                                 """)
+                        .options(allOptions)
+                        .outdir(classes)
+                        .run()
+                        .writeAll()
+                        .getOutputLines(Task.OutputKind.DIRECT);
+
+            assertEquals(expected, out);
+        }
+    }
+
+    public static final class ProcessorImpl extends JavacTestingAbstractProcessor {
+        @Override
+        public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
+            return false;
+        }
+    }
+}

